// RED histogram labels (bounded)
const labels = { route: 200, method: 5, status_class: 4, region: 3 };
const BUCKETS = 12;          // histogram le-buckets per label-set
const RAM_PER_SERIES = 3 * 1024; // ~3 KB

function labelSets(dims) {
  return Object.values(dims).reduce((a, b) => a * b, 1);
}
function series(dims, buckets) {
  return labelSets(dims) * buckets;
}
function gib(bytes) {
  return (bytes / 1024 ** 3).toFixed(2) + ' GiB';
}

const base = series(labels, BUCKETS);
console.log('label-sets:', labelSets(labels));
console.log('series (×' + BUCKETS + ' buckets):', base);
console.log('RAM:', gib(base * RAM_PER_SERIES));

