function seriesCount(dims) {
  // dims: { labelName: numberOfDistinctValues, ... }
  let total = 0;
  for (const name in dims) {
    total += dims[name];
  }
  return total;
}

function fitsBudget(dims, budget) {
  return seriesCount(dims) <= budget;
}

